head.b:skin:
/* --- CSS RESET & VARIABLES --- */
:root {
  --bg-color: #050505;
  --primary: #a855f7; /* Neon Purple */
  --text-main: #ffffff;
  --text-muted: #9ca3af; /* Gray 400 */
  --card-bg: #111111;
  --font-main: 'Montserrat', sans-serif;
}

* { margin: 0; padding: 0; box-sizing: border-box; }
body { background-color: var(--bg-color); color: var(--text-main); font-family: var(--font-main); overflow-x: hidden; }
a { text-decoration: none; color: inherit; }
ul { list-style: none; }

/* --- NAVBAR --- */
header { display: flex; justify-content: space-between; align-items: center; padding: 20px 50px; background: rgba(5,5,5,0.9); position: sticky; top: 0; z-index: 100; border-bottom: 1px solid #222; backdrop-filter: blur(10px); }
.logo { font-size: 24px; font-weight: 800; letter-spacing: 1px; }
.logo span { color: var(--primary); }
.nav-links { display: flex; gap: 30px; }
.nav-links a { font-size: 14px; font-weight: 600; transition: color 0.3s; }
.nav-links a:hover { color: var(--primary); }

/* --- HERO SECTION --- */
.hero { 
  height: 90vh; 
  display: flex; 
  flex-direction: column; 
  justify-content: center; 
  align-items: center; 
  text-align: center; 
  position: relative; 
  background: linear-gradient(rgba(0,0,0,0.75), rgba(0,0,0,0.85)), url('https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEh-C-2bcVDDUKY3S9xvUQ7s-o3s87EEOnF227N2Y6uKjC0O9D_KLR2YlWR4eoPcFCdEwxp5GnUPnR4YRNYi5Po2hHaQtFNshZWT0XjNUIbwOiFZVgjl-I68ES5-guOPwJd_nfevEjGsdTj0QihRofEucKk_l7WLDZpswXmlEaedLNPVtutQa6deXnUpfCk/s16000/Adhikari%20Studio.png') center center / cover no-repeat;
}
.hero-icon { font-size: 40px; color: var(--primary); margin-bottom: 20px; z-index: 2; }
.hero h1 { font-size: 80px; font-weight: 800; margin-bottom: 10px; z-index: 2; line-height: 1.1; }
.hero h1 span { color: var(--primary); }
.hero p { font-size: 18px; letter-spacing: 4px; color: var(--text-muted); margin-bottom: 40px; z-index: 2; text-transform: uppercase; }
.hero-buttons { display: flex; gap: 20px; z-index: 2; }
.btn { padding: 15px 40px; font-size: 14px; font-weight: 700; cursor: pointer; border-radius: 4px; transition: all 0.3s; display: flex; align-items: center; justify-content: center; gap: 10px; }
.btn-primary { background: var(--primary); color: #fff; border: none; }
.btn-primary:hover { background: #9333ea; box-shadow: 0 0 20px rgba(168,85,247,0.5); }
.btn-outline { background: transparent; color: #fff; border: 2px solid #fff; }
.btn-outline:hover { background: #fff; color: #000; }

/* --- SCROLL INDICATOR --- */
.scroll-indicator { position: absolute; bottom: 32px; left: 50%; transform: translateX(-50%); z-index: 10; animation: tailwindBounce 1s infinite; }
@keyframes tailwindBounce { 0%, 100% { transform: translate(-50%, -25%); animation-timing-function: cubic-bezier(0.8,0,1,1); } 50% { transform: translate(-50%, 0); animation-timing-function: cubic-bezier(0,0,0.2,1); } }
.mouse { width: 24px; height: 40px; border: 2px solid #ffffff; border-radius: 9999px; display: flex; align-items: flex-start; justify-content: center; padding: 8px; }
.wheel { width: 4px; height: 12px; background: #ffffff; border-radius: 9999px; }

/* --- ABOUT SECTION --- */
.section { padding: 100px 50px; max-width: 1200px; margin: 0 auto; }
.about-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center; }

.about-img-wrapper { position: relative; }
.about-img-wrapper::before { content: ''; position: absolute; top: -10px; left: -10px; right: -10px; bottom: -10px; background: rgba(168, 85, 247, 0.2); filter: blur(20px); z-index: -1; border-radius: 15px; }
.about-img { width: 100%; height: 80vh; object-fit: cover; border-radius: 10px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.5); position: relative; z-index: 1; }

.about-content h2 { font-size: 40px; font-weight: 800; margin-bottom: 30px; }
.about-content h2 span { color: var(--primary); }
.about-content p { color: var(--text-muted); line-height: 1.8; margin-bottom: 20px; font-size: 15px; }
.stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; margin-top: 32px; }
.stat-item { text-align: center; }
.stat-item h3 { color: var(--primary); font-size: 30px; font-weight: 800; margin-bottom: 8px; line-height: 1; }
.stat-item p { color: var(--text-muted); font-size: 14px; letter-spacing: 1px; text-transform: uppercase; margin: 0; font-weight: 600; }

/* --- MUSIC SECTION --- */
#music { background: linear-gradient(to bottom, #000000, rgba(59, 7, 100, 0.2)); padding: 96px 50px; }
.music-container { max-width: 1280px; margin: 0 auto; }
.music-header h2 { font-size: 48px; margin-bottom: 16px; text-align: center; font-weight: 800; }
.music-header h2 span { color: var(--primary); }
.music-header p { text-align: center; color: var(--text-muted); margin-bottom: 48px; font-size: 16px; }

.music-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
.music-card { background: linear-gradient(to bottom, #111827, #000000); border: 1px solid rgba(255, 255, 255, 0.1); position: relative; overflow: hidden; transition: all 0.3s ease; border-radius: 8px; }
.music-card:hover { border-color: rgba(168, 85, 247, 0.5); }
.music-img-wrapper { width: 100%; aspect-ratio: 1 / 1; overflow: hidden; }
.music-img { width: 100%; height: 100%; object-fit: cover; transition: transform 0.5s ease; }
.music-card:hover .music-img { transform: scale(1.1); }
.music-content { padding: 24px; }
.music-year { color: var(--primary); font-size: 14px; margin-bottom: 8px; }
.music-title { font-size: 24px; font-weight: 700; margin-bottom: 8px; }
.music-tracks { color: var(--text-muted); font-size: 16px; margin-bottom: 16px; }

.btn-card-play { width: 100%; padding: 12px; background: #9333ea; color: #fff; display: flex; align-items: center; justify-content: center; gap: 8px; border: none; cursor: pointer; transition: background 0.3s; font-size: 16px; font-weight: 600; border-radius: 4px; text-decoration: none; }
.btn-card-play:hover { background: #7e22ce; color: #fff; }
.btn-card-play i { transition: transform 0.3s; }
.music-card:hover .btn-card-play i { transform: scale(1.1); }

.play-overlay { position: absolute; top: 16px; right: 16px; width: 48px; height: 48px; background: rgba(0, 0, 0, 0.8); backdrop-filter: blur(4px); border-radius: 50%; display: flex; align-items: center; justify-content: center; opacity: 0; transition: all 0.3s ease; z-index: 10; text-decoration: none; color: var(--primary); cursor: pointer; }
.music-card:hover .play-overlay { opacity: 1; }
.play-overlay:hover { transform: scale(1.1); background: rgba(168, 85, 247, 0.2); }
.play-overlay i { font-size: 20px; margin-left: 3px; }

/* --- LISTEN ON SECTION --- */
.listen-on-section { margin-top: 64px; text-align: center; }
.listen-on-section h3 { font-size: 24px; margin-bottom: 24px; font-weight: 600; }
.listen-on-grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 16px; }
.platform-btn { display: flex; align-items: center; justify-content: center; gap: 8px; padding: 12px 24px; font-size: 16px; font-weight: 600; cursor: pointer; border: none; color: #fff; transition: background 0.3s; border-radius: 4px; text-decoration: none; }

/* Platform Colors */
.spotify { background: #1db954; color: #fff; } .spotify:hover { background: #1ed760; }
.apple { background: #fa243c; color: #fff; } .apple:hover { background: #ff3b53; }
.soundcloud { background: #ff5500; color: #fff; } .soundcloud:hover { background: #ff7700; }
.amazon-music { background: #00a8e1; color: #fff; } .amazon-music:hover { background: #008cc0; }

/* --- TOUR SECTION --- */
#tour { padding: 96px 50px; max-width: 1280px; margin: 0 auto; }
.tour-header { text-align: center; margin-bottom: 48px; }
.tour-header h2 { font-size: 48px; font-weight: 800; margin-bottom: 16px; }
.tour-header h2 span { color: var(--primary); }
.tour-header p { color: var(--text-muted); font-size: 16px; }
.tour-list { display: flex; flex-direction: column; gap: 16px; }
.tour-box { background: linear-gradient(to right, #111827, #000000); border: 1px solid rgba(255, 255, 255, 0.1); padding: 24px; transition: all 0.3s ease; border-radius: 8px; }
.tour-box:hover { border-color: rgba(168, 85, 247, 0.5); }
.tour-row { display: flex; flex-direction: column; gap: 16px; }
@media (min-width: 768px) { .tour-row { flex-direction: row; align-items: center; justify-content: space-between; } }
.tour-details { flex: 1; display: grid; gap: 16px; }
@media (min-width: 768px) { .tour-details { grid-template-columns: repeat(3, 1fr); } }
.detail-item { display: flex; align-items: center; gap: 12px; }
.detail-item svg { flex-shrink: 0; color: var(--primary); }
.detail-item span { color: #fff; font-size: 16px; }
.detail-item .font-mono { font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", "Courier New", monospace; }
.detail-item .text-muted { color: var(--text-muted); }
.tour-actions { display: flex; align-items: center; gap: 16px; }
.status-badge { font-size: 14px; padding: 4px 12px; border-radius: 4px; text-align: center; font-weight: 600; }
.status-available { background: rgba(22, 163, 74, 0.2); color: #22c55e; }
.status-soldout { background: rgba(220, 38, 38, 0.2); color: #ef4444; }
.status-limited { background: rgba(202, 138, 4, 0.2); color: #eab308; }
.btn-ticket { padding: 8px 24px; font-weight: 600; font-size: 16px; min-width: 120px; transition: background 0.3s; border: none; cursor: pointer; color: #fff; text-align: center; border-radius: 4px; }
.btn-ticket.active { background: #9333ea; }
.btn-ticket.active:hover { background: #7e22ce; }
.btn-ticket.disabled { background: #374151; color: #9ca3af; cursor: not-allowed; }

/* --- BUY ME A COFFEE CTA SECTION (NEON UPGRADE) --- */
.bmc-cta { 
  position: relative; 
  overflow: hidden; 
  text-align: center; 
  margin-top: 80px; 
  padding: 50px 20px; 
  background: linear-gradient(145deg, #050505, #111111); 
  border-radius: 12px; 
  border: 1px solid rgba(168, 85, 247, 0.3); 
  box-shadow: 0 0 30px rgba(168, 85, 247, 0.1); 
}
.floating-coins { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; z-index: 0; }
.coin { position: absolute; color: rgba(168, 85, 247, 0.15); animation: floatUp linear infinite; bottom: -50px; }
@keyframes floatUp { 
  0% { transform: translateY(0) scale(0.5) rotate(0deg); opacity: 0; } 
  10% { opacity: 1; } 
  90% { opacity: 1; } 
  100% { transform: translateY(-300px) scale(1.2) rotate(360deg); opacity: 0; } 
}
.coin:nth-child(1) { left: 10%; animation-duration: 4s; animation-delay: 0s; font-size: 24px; }
.coin:nth-child(2) { left: 25%; animation-duration: 5s; animation-delay: 2s; font-size: 16px; }
.coin:nth-child(3) { left: 45%; animation-duration: 4.5s; animation-delay: 1s; font-size: 20px; }
.coin:nth-child(4) { left: 65%; animation-duration: 6s; animation-delay: 3s; font-size: 18px; }
.coin:nth-child(5) { left: 85%; animation-duration: 5.5s; animation-delay: 0.5s; font-size: 26px; }
.coin:nth-child(6) { left: 15%; animation-duration: 4.8s; animation-delay: 2.5s; font-size: 18px; }
.coin:nth-child(7) { left: 75%; animation-duration: 5.2s; animation-delay: 1.5s; font-size: 22px; }

.bmc-icon-wrapper { margin-bottom: 15px; position: relative; z-index: 2; }
.bmc-icon { font-size: 45px; color: var(--primary); filter: drop-shadow(0 0 15px rgba(168,85,247,0.6)); }
.bmc-text { color: var(--text-main); font-size: 22px; font-weight: 700; margin-bottom: 25px; line-height: 1.5; position: relative; z-index: 2; }

.bmc-btn { display: inline-flex; align-items: center; justify-content: center; gap: 10px; padding: 14px 28px; background: var(--primary); color: #ffffff; font-weight: 700; font-size: 16px; border: none; cursor: pointer; transition: all 0.3s; border-radius: 6px; text-decoration: none; position: relative; z-index: 2; font-family: inherit;}
.bmc-btn:hover { background: #9333ea; transform: translateY(-3px); box-shadow: 0 10px 25px rgba(168, 85, 247, 0.4); }
.bmc-btn svg { width: 22px; height: 22px; fill: #ffffff; }

/* --- FOOTER SECTION --- */
footer { background: #000000; border-top: 1px solid rgba(255, 255, 255, 0.1); padding: 60px 20px 30px; }
.footer-container { max-width: 1280px; margin: 0 auto; }

/* Perfect 3 Column Grid */
.footer-grid { display: grid; gap: 32px; margin-bottom: 40px; }
@media (min-width: 768px) { .footer-grid { grid-template-columns: repeat(3, 1fr); } }

.footer-col h3 { font-size: 24px; margin-bottom: 16px; font-weight: 700; }
.footer-col h3 span { color: var(--primary); }
.footer-col p { color: var(--text-muted); line-height: 1.6; font-size: 14px; }

.footer-col h4 { font-size: 18px; margin-bottom: 16px; font-weight: 600; color: #fff; }

.footer-links { display: flex; flex-direction: column; gap: 12px; }
.footer-links a, .footer-links button { color: var(--text-muted); background: none; border: none; cursor: pointer; text-align: left; font-size: 16px; padding: 0; transition: color 0.3s; font-family: inherit; }
.footer-links a:hover, .footer-links button:hover { color: var(--primary); }

/* Social Row Spacing */
.social-row { display: flex; gap: 16px; }
.social-icon { width: 48px; height: 48px; background: rgba(255, 255, 255, 0.1); border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; transition: background 0.3s; text-decoration: none; font-size: 20px; }
.social-icon:hover { background: var(--primary); }

/* Newsletter spacing */
.newsletter-section { margin-top: 24px; }
.newsletter-label { font-size: 14px; margin-bottom: 10px; font-weight: 600; display: block; color: #fff; }
.newsletter-form { display: flex; gap: 8px; }
.newsletter-input { flex: 1; padding: 10px 16px; background: rgba(255, 255, 255, 0.1); border: 1px solid rgba(255, 255, 255, 0.2); color: #fff; outline: none; font-family: inherit; transition: border-color 0.3s; }
.newsletter-input:focus { border-color: var(--primary); }
.btn-subscribe { padding: 10px 20px; background: var(--primary); color: #fff; border: none; font-weight: 600; cursor: pointer; transition: background 0.3s; font-family: inherit; }
.btn-subscribe:hover { background: #9333ea; }

.footer-bottom { padding-top: 32px; border-top: 1px solid rgba(255, 255, 255, 0.1); text-align: center; color: var(--text-muted); font-size: 14px; }

/* ========================================= */
/* 📱 MOBILE RESPONSIVENESS                  */
/* ========================================= */
@media (max-width: 768px) {
  .section, #music, #tour, footer { padding: 60px 20px; }
  header { flex-direction: column; padding: 15px 20px; gap: 15px; }
  .nav-links { flex-wrap: wrap; justify-content: center; gap: 15px; }
  .hero h1 { font-size: 45px; }
  .hero p { font-size: 12px; letter-spacing: 2px; padding: 0 10px; }
  .hero-buttons { flex-direction: column; width: 100%; max-width: 300px; gap: 15px; }
  .btn { width: 100%; padding: 15px; }
  .about-grid { grid-template-columns: 1fr; gap: 40px; }
  .about-img { height: 450px; }
  .about-content h2 { font-size: 32px; text-align: center; }
  .about-content p { text-align: left; }
  .stats { gap: 15px; }
  .stat-item h3 { font-size: 24px; }
  .stat-item p { font-size: 11px; }
  .music-header h2 { font-size: 36px; }
  .music-grid { grid-template-columns: 1fr; gap: 20px; }
  .listen-on-grid { flex-direction: column; width: 100%; align-items: stretch; }
  .platform-btn { width: 100%; }
  .tour-header h2 { font-size: 36px; }
  .tour-box { padding: 15px; }
  .tour-details { grid-template-columns: 1fr; gap: 12px; }
  .tour-actions { flex-direction: column; width: 100%; align-items: stretch; gap: 10px; margin-top: 10px; }
  .status-badge { width: 100%; }
  .btn-ticket { width: 100%; }

  .bmc-cta { padding: 40px 20px; margin-top: 60px; }
  .bmc-text { font-size: 18px; }
  .bmc-btn { width: 100%; max-width: 300px; padding: 14px 20px; font-size: 15px; }

  .footer-grid { grid-template-columns: 1fr; gap: 40px; text-align: left; }
  .footer-col h3, .footer-col h4 { text-align: left; }
  .footer-links { align-items: flex-start; }
  .newsletter-form { flex-direction: column; gap: 10px; }
  .newsletter-input { width: 100%; }
  .btn-subscribe { width: 100%; }
}

#blogger-widgets { display: none; }

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//
